// Interface and speech language. Translations come from i18n_table.h (generated by gen_ui.py).
#pragma once

enum class TrString;

void i18n_begin();                 // load saved languages from NVS and apply (after ui_init)
void i18n_set_ui(int lang);        // index into I18N_CODES; relabels every screen, saved
void i18n_set_speech(int choice);  // 0 = same as interface, 1.. = I18N_CODES[choice - 1]; saved
int i18n_ui();
const char *i18n_ui_code();        // "en", "de", ...
const char *i18n_speech_code();    // "en", "de", "fr", "it", "pt-PT": for the companion's whisper + Piper
const char *i18n_str(TrString s);  // a firmware text in the current interface language
